public static class QueueApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("QUEUE-003", "guests walk to the join cell, the path cell attached to the back of the queue (the first cardinal neighbour in the order 1, 4, 16, 64 whose bit is set in the back cell's link byte +0x0C, tp.exe 0x4DE840), and join from it; tp.exe's state-10 join (0x4FFBC0) needs the guest's own cell to be the back queue cell (0x4DE110, 0x4DE130), reached through the back cell's link by the walk's edge test 0x4D8750, and uses the attached path cell only for the back cell's fourth place; OpenTPW's ride entrance cell keeps no link byte (ride cells are not typed map cells, WALK-005), so the ride keeps its front in QueueFrontCell where tp.exe reads it from the entrance cell's bit (0x4DE040)"),
		("QUEUE-005", "after a queue edit a guest beyond the new room leaves as tp.exe's 0x501390 sends it, and the others change nothing there (state 11 later re-routes a guest whose place changed through 0x501160) (a guest whose cell left the queue is routed to its new place from where it stands, by the walk search 0x4fa5f0, and leaves only when that fails); a guest sent away thinks Angry by OpenTPW's guest id modulo 3 rather than its thing id (word at thing +0), and its dismissal (0x5012f0) neither records event 6 with the ride id in the guest's event ring (read only by the debug dump 0x4faa60) nor plays the sound for a thing id whose low three bits are 0"),
